use mdd_sql::{SqlBridge,control::{SqlControl,SqlLimits},dialects::SqlDialect,provider::{SqlBinding,SqlColumn,SqlFactCursor,SqlFactProvider,SqlRelation,SqlRow},values::{SqlType,SqlValue}};
use mdd_types::{DecimalU64,ErrorCode,MddError,MddResult};use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
struct P{binding:SqlBinding,mode:&'static str,requires:AtomicUsize,opens:AtomicUsize}struct C{rows:std::vec::IntoIter<SqlRow>,mode:&'static str,position:usize}
impl SqlFactCursor for C{fn next_row(&mut self)->MddResult<Option<SqlRow>>{if self.mode=="invalid_input"&&self.position==1{return Err(MddError::new(ErrorCode::InvalidInput,"fixture.cursor","synthetic corrupt member"));}let r=self.rows.next();self.position+=usize::from(r.is_some());Ok(r)}}
fn col(n:&str,t:SqlType,nullable:bool)->SqlColumn{SqlColumn{id:n.into(),name:n.into(),data_type:t,nullable}}
impl SqlFactProvider for P{
 fn binding(&self)->&SqlBinding{&self.binding}
 fn relations(&self)->MddResult<Vec<SqlRelation>>{let fields=[("file_id",SqlType::U64,false),("annotation_off",SqlType::U64,false),("depth",SqlType::U64,false),("ordinal",SqlType::U64,false),("name_idx",SqlType::U64,true),("value_off",SqlType::U64,false),("value_end_off",SqlType::U64,false),("value_kind",SqlType::Text,false),("value_index",SqlType::U64,true),("value_i64",SqlType::I64,true),("value_f64",SqlType::F64,true)];Ok(vec![SqlRelation{name:"annotation_elements".into(),columns:fields.iter().map(|(n,t,x)|col(n,*t,*x)).collect(),required_layers:vec![],estimated_rows:Some(DecimalU64(7))}])}
 fn require_relation(&self,_:&str)->MddResult<()>{self.requires.fetch_add(1,Ordering::SeqCst);if self.mode=="missing"{Err(MddError::new(ErrorCode::IncompleteFacts,"fixture.coverage","required annotations unavailable"))}else{Ok(())}}
 fn open_cursor(self:Arc<Self>,_:&str,_:SqlControl)->MddResult<Box<dyn SqlFactCursor>>{self.opens.fetch_add(1,Ordering::SeqCst);let input=if self.mode.starts_with("oracle_"){include_str!("../oracle-fixture.json")}else{include_str!("../fixture.json")};let data:Vec<Vec<serde_json::Value>>=serde_json::from_str(input).unwrap();let rows=data.into_iter().map(|row|row.into_iter().enumerate().map(|(i,v)|if v.is_null(){SqlValue::Null}else if let Some(s)=v.as_str(){SqlValue::text(s)}else if i==9{SqlValue::I64(mdd_query::ir::Signed64(v.as_i64().unwrap()))}else{SqlValue::U64(DecimalU64(v.as_u64().unwrap()))}).collect()).collect::<Vec<_>>();Ok(Box::new(C{rows:rows.into_iter(),mode:self.mode,position:0}))}
}
fn main(){let q04="SELECT file_id,annotation_off,ordinal,value_index FROM annotation_elements WHERE ((file_id=0 AND annotation_off IN (256))) AND depth=1 AND value_kind='string' ORDER BY file_id,annotation_off,ordinal";
 let grouped="SELECT file_id,annotation_off,ordinal,value_index FROM annotation_elements WHERE ((file_id=0 AND annotation_off IN (256,257)) OR (file_id=1 AND annotation_off IN (256))) AND depth=1 AND value_kind='string' ORDER BY file_id,annotation_off,ordinal";
 let oracle_q04="SELECT file_id,annotation_off,ordinal,value_index FROM annotation_elements WHERE ((file_id=0 AND annotation_off IN (1000))) AND depth=1 AND value_kind='string' ORDER BY file_id,annotation_off,ordinal";
 let oracle_grouped="SELECT file_id,annotation_off,ordinal,value_index FROM annotation_elements WHERE ((file_id=0 AND annotation_off IN (1000,999999)) OR (file_id=1 AND annotation_off IN (1000))) AND depth=1 AND value_kind='string' ORDER BY file_id,annotation_off,ordinal";
 let mut out=vec![];for (dialect_name,dialect) in [("010",SqlDialect::DexSql010),("011",SqlDialect::DexSql011)]{for (mode,sql) in [("q04",q04),("grouped",grouped),("oracle_q04",oracle_q04),("oracle_grouped",oracle_grouped),("missing","SELECT * FROM annotation_elements LIMIT 0"),("invalid_input",q04)]{
 let p=Arc::new(P{binding:SqlBinding{provider_identity:"synthetic-q04".into(),snapshot_id:"fixture-only".into(),catalog_epoch:DecimalU64(0)},mode,requires:AtomicUsize::new(0),opens:AtomicUsize::new(0)});let bridge=SqlBridge::new(p.clone(),dialect,SqlLimits::default()).unwrap();
 let result=match bridge.query(sql){Ok(r)=>serde_json::json!({"status":"ok","value":r}),Err(e)=>serde_json::json!({"status":"error","error":e})};out.push(serde_json::json!({"dialect":dialect_name,"mode":mode,"sql":sql,"result":result,"requires":p.requires.load(Ordering::SeqCst),"opens":p.opens.load(Ordering::SeqCst)}));}}
 println!("{}",serde_json::to_string(&out).unwrap());}
